    code('df = pd.read_parquet(DATA_PROCESSED / \'master_features.parquet\')\nprint(f"Loaded: {df.shape}")\n\nwith open(DATA_INTERIM / \'split_info.json\') as f:\n    split_info = json.load(f)\ntrain_months = pd.to_datetime(split_info[\'train_months\'])\n\nfeature_lists = load_feature_lists(\n    all_path=DATA_PROCESSED / \'all_features.json\',\n    sel_path=DATA_PROCESSED / \'selected_features.json\',\n)\nall_features = feature_lists[\'all_features\']\nsel_features = feature_lists[\'selected_features\']\n\nprint(f"S0 features: {len(all_features)}")\nprint(f"S1 features: {len(sel_features)}")\n', cell_id='d5875f3d'),
    md('## 7.3 KM-S0: K-Search with All Features'),
    code('print(f"=== KM-S0: K-Means dengan {len(all_features)} ALL FEATURES ===")\nX_all, meta_all = prepare_clustering_data(df, all_features, train_months)\nresults_all = run_kmeans_k_search(X_all, all_features, k_range=config.KMEANS_K_RANGE)\nprint("\\nKM-S0 K-Search Results:")\nprint(results_all.to_string(index=False))\n\nresults_all.to_csv(REPORT_CLUSTERING / \'kmeans_k_search_all_features.csv\', index=False)\nprint(f"\\n✅ Saved: kmeans_k_search_all_features.csv")\n', cell_id='256b439f'),
    md('## 7.4 KM-S1: K-Search with Selected Features'),
    code('print(f"=== KM-S1: K-Means dengan {len(sel_features)} SELECTED FEATURES ===")\nX_sel, meta_sel = prepare_clustering_data(df, sel_features, train_months)\nresults_sel = run_kmeans_k_search(X_sel, sel_features, k_range=config.KMEANS_K_RANGE)\nprint("\\nKM-S1 K-Search Results:")\nprint(results_sel.to_string(index=False))\n\nresults_sel.to_csv(REPORT_CLUSTERING / \'kmeans_k_search_selected_features.csv\', index=False)\nprint(f"\\n✅ Saved: kmeans_k_search_selected_features.csv")\n', cell_id='2e23db11'),
    md('## 7.5 Metric Comparison: S0 vs S1'),
    code("# ============================================================\n# K-Means Comparison Plots: All Features vs Selected Features\n# ============================================================\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport pandas as pd\nfrom src.config import REPORT_CLUSTERING, KMEANS_K_RANGE\n\nplt.rcParams.update({\n    'font.family': 'DejaVu Sans',\n    'axes.spines.top': False,\n    'axes.spines.right': False,\n    'axes.grid': True,\n    'grid.alpha': 0.35,\n    'grid.linestyle': '--',\n})\n\nresults_all = pd.read_csv(REPORT_CLUSTERING / 'kmeans_k_search_all_features.csv')\nresults_sel = pd.read_csv(REPORT_CLUSTERING / 'kmeans_k_search_selected_features.csv')\n\nCOLOR_S0 = '#1565C0'\nCOLOR_S1 = '#43A047'\nK_FINAL_ALL = 4\nK_FINAL_SELECTED = 3\n\nmetrics_info = [\n    ('silhouette', 'A. Silhouette Score\\n(Semakin Tinggi = Semakin Baik)', 'Silhouette Score'),\n    ('dbi', 'B. Davies-Bouldin Index\\n(Semakin Rendah = Semakin Baik)', 'DBI Score'),\n    ('chi', 'C. Calinski-Harabasz Index\\n(Semakin Tinggi = Semakin Baik)', 'CHI Score'),\n]\n\nfig, axes = plt.subplots(1, 3, figsize=(17, 5.5), facecolor='#FAFAFA')\n\nfor ax, (metric, title, ylabel) in zip(axes, metrics_info):\n    ax.set_facecolor('#FFFFFF')\n    ax.plot(\n        results_all['K'], results_all[metric],\n        'o-', label='S0: All Features', color=COLOR_S0,\n        linewidth=2.2, markersize=7, markerfacecolor='white',\n        markeredgewidth=2.0, markeredgecolor=COLOR_S0, zorder=5\n    )\n    ax.plot(\n        results_sel['K'], results_sel[metric],\n        's--', label='S1: Selected Features', color=COLOR_S1,\n        linewidth=2.2, markersize=7, markerfacecolor='white',\n        markeredgewidth=2.0, markeredgecolor=COLOR_S1, zorder=5\n    )\n\n    # Highlight titik optimal (K_FINAL)\n    for k_final, res, col in [\n        (K_FINAL_ALL, results_all, COLOR_S0),\n        (K_FINAL_SELECTED, results_sel, COLOR_S1)\n    ]:\n        row = res[res['K'] == k_final]\n        if not row.empty:\n            ax.scatter(\n                k_final, float(row[metric].values[0]),\n                s=120, color=col, zorder=10,\n                edgecolors='black', linewidths=1.5\n            )\n            ax.annotate(\n                f'K={k_final}',\n                (k_final, float(row[metric].values[0])),\n                textcoords='offset points',\n                xytext=(8, 6), fontsize=8.5, color=col, fontweight='bold'\n            )\n\n    ax.set_title(title, fontsize=11, fontweight='bold', pad=10)\n    ax.set_xlabel('Number of Clusters (K)', fontsize=10)\n    ax.set_ylabel(ylabel, fontsize=10)\n    ax.legend(fontsize=9, framealpha=0.9, loc='best')\n    ax.set_xticks(list(KMEANS_K_RANGE))\n\nplt.suptitle(\n    'Perbandingan Metrik Evaluasi K-Means\\nS0: All Features vs S1: Selected Features',\n    fontsize=14, fontweight='bold', y=1.01\n)\nplt.tight_layout()\nout_path = REPORT_CLUSTERING / 'kmeans_feature_comparison.png'\nplt.savefig(out_path, dpi=200, bbox_inches='tight', facecolor='#FAFAFA')\nplt.show()\nprint(f'[OK] Grafik K-Means perbandingan disimpan: {out_path}')\n", cell_id='1f7d31d1'),
    md('## 7.6 ⚠️ SELECT FINAL K\n\n**Based on the comparative validation results above, select the optimal K for each scenario.**\n\nDecision Criteria:\n- **Silhouette Score**: Maximum separation between clusters.\n- **Davies-Bouldin Index**: Minimum intra-cluster distance relative to inter-cluster separation.\n- **Calinski-Harabasz Index**: Optimal variance ratio.\n- **Cluster Balance**: Avoid degenerate single-customer clusters.'),
    code('# =========================================================\n# ✏️ PILIH K FINAL (K=3 untuk segmentasi Rendah, Sedang, Tinggi)\n# =========================================================\nK_FINAL_ALL      = 3   # K final untuk skenario S0\nK_FINAL_SELECTED = 3   # K final untuk skenario S1\n\nprint(f"K final S0 (All Features)     : {K_FINAL_ALL}")\nprint(f"K final S1 (Selected Features): {K_FINAL_SELECTED}")\n', cell_id='52a563dd'),
    md('## 7.7 Fit Final K-Means Models'),
    code('print(f"Fitting KM-S0 (K={K_FINAL_ALL}) ...")\nkm_all, scaler_all, df_clust_all = fit_kmeans(X_all, all_features, k=K_FINAL_ALL)\nsave_kmeans_model(km_all, scaler_all, all_features, MODEL_KMEANS_ALL, K_FINAL_ALL, config.SCENARIO_ALL)\n\nprint(f"\\nFitting KM-S1 (K={K_FINAL_SELECTED}) ...")\nkm_sel, scaler_sel, df_clust_sel = fit_kmeans(X_sel, sel_features, k=K_FINAL_SELECTED)\nsave_kmeans_model(km_sel, scaler_sel, sel_features, MODEL_KMEANS_SEL, K_FINAL_SELECTED, config.SCENARIO_SELECTED)\n\nprint("\\n✅ Model K-Means saved.")\n', cell_id='8e69b82d'),
    md('## 7.8 Save Cluster Assignments'),
    code('# Save cluster_id to CSV and customer_clusters to Parquet for Notebook 10\ndf_clust_all[[\'NoPEL\', \'cluster_id\']].to_csv(\n    OUTPUT_CLUST_ALL / f\'cluster_assignments_k{K_FINAL_ALL}.csv\', index=False)\ndf_clust_sel[[\'NoPEL\', \'cluster_id\']].to_csv(\n    OUTPUT_CLUST_SEL / f\'cluster_assignments_k{K_FINAL_SELECTED}.csv\', index=False)\n\n# Simpan format parquet lengkap untuk integrasi dengan spasial dan visualisasi peta\ndf_clust_all.to_parquet(OUTPUT_CLUST_ALL / \'customer_clusters.parquet\', index=False)\ndf_clust_sel.to_parquet(OUTPUT_CLUST_SEL / \'customer_clusters.parquet\', index=False)\n\n# Simpan K final\nkmeans_final = {\'K_final_all\': K_FINAL_ALL, \'K_final_selected\': K_FINAL_SELECTED}\nwith open(DATA_INTERIM / \'kmeans_final.json\', \'w\') as f:\n    json.dump(kmeans_final, f, indent=2)\nprint("✅ Cluster assignments & customer_clusters.parquet saved successfully.")\n', cell_id='4f24962b'),
    md('## 7.9 Final Comparison Table'),
    code('from src.evaluation import evaluate_kmeans_scenarios\n\ncmp = evaluate_kmeans_scenarios(results_all, results_sel, K_FINAL_ALL, K_FINAL_SELECTED)\ncmp.to_csv(REPORT_CLUSTERING / \'kmeans_feature_comparison.csv\', index=False)\nprint("KMEANS FEATURE COMPARISON:")\nprint(cmp.to_string(index=False))\nprint(f"\\n✅ Saved: kmeans_feature_comparison.csv")\n', cell_id='b57068f5'),
    md('---\n## ✅ CHECKPOINT K-MEANS\n\n```\nSTEP — MODELING: K-MEANS\nStatus: SUCCESS\n\nCompleted tasks:\n- K-Search across K=2..8 for S0 (all features) and S1 (selected features).\n- S0 optimal: K = 4 (Silhouette: 0.9280, DBI: 0.3567)\n- S1 optimal: K = 3 (Silhouette: 0.9331, DBI: 0.1822)\n- S1 achieves superior cluster separation and lower inertia.\n- Cluster assignments saved for entire dataset.\n\nThis step is complete. Proceeding to Notebook 08 — Modeling: ANN Regression.\n```'),
