    md('# Notebook 09 — Evaluation: Final Comparison (ANN Regression & K-Means)\n**CRISP-DM Phase:** Evaluation\n\n> Comprehensive performance evaluation comparing K-Means clustering and ANN regression across all scenarios.\n> Ablation analysis: Baseline vs Global S0 vs Global S1 vs Cluster-dedicated models.\n> Export final selected pipeline configurations.'),
    md('## 9.1 Setup & Libraries'),
    code('import sys, warnings\nsys.path.insert(0, \'..\')\nwarnings.filterwarnings(\'ignore\')\n\nimport pandas as pd\nimport numpy as np\nimport json\nimport matplotlib.pyplot as plt\n\nfrom src import config\nfrom src.config import (\n    DATA_INTERIM, DATA_PROCESSED, REPORT_EVALUATION,\n    REPORT_CLUSTERING, ensure_dirs\n)\nfrom src.evaluation import (\n    compute_regression_metrics, evaluate_observed_only,\n    build_final_pipeline_comparison\n)\nensure_dirs()\nprint("✅ Setup complete.")\n', cell_id='9371399f'),
    md('## 9.2 Load All Modeling Results'),
    code('with open(DATA_INTERIM / \'ann_results.json\') as f:\n    ann_results = json.load(f)\n\ny_pred_s0 = np.load(DATA_INTERIM / \'y_pred_s0_test.npy\')\ny_pred_s1 = np.load(DATA_INTERIM / \'y_pred_s1_test.npy\')\n\ndf = pd.read_parquet(DATA_PROCESSED / \'master_features.parquet\')\nwith open(DATA_INTERIM / \'split_info.json\') as f:\n    si = json.load(f)\ntest_months = pd.to_datetime(si[\'test_months\'])\ndf_test = df[df[\'period_dt\'].isin(test_months)].copy()\n# Filter target fisik valid (non-negative) konsisten dengan Notebook 08\ndf_test_valid = df_test[df_test[config.TARGET_COL].notna() & (df_test[config.TARGET_COL] >= 0)].copy().reset_index(drop=True)\n\nprint(f"Test set valid: {len(df_test_valid):,} customers")\n', cell_id='d5d897ae'),
    md('## 9.3 ANN Regression Model Evaluation Table'),
    code('all_metrics = []\n# Fokus pada Model ANN Regression S0 dan S1\nall_metrics.append({**ann_results[\'ann_global_s0\'], \'scenario\': config.SCENARIO_ALL, \'n_features\': len(ann_results[\'ann_global_s0\'].get(\'features\', [])) or 18, \'model_type\': \'ANN_Regression\'})\nall_metrics.append({**ann_results[\'ann_global_s1\'], \'scenario\': config.SCENARIO_SELECTED, \'n_features\': len(ann_results[\'ann_global_s1\'].get(\'features\', [])) or 3, \'model_type\': \'ANN_Regression\'})\nfor m in ann_results.get(\'ann_cluster_s0\', []):\n    all_metrics.append({**m, \'scenario\': config.SCENARIO_ALL, \'model_type\': \'ANN_Cluster_S0\'})\nfor m in ann_results.get(\'ann_cluster_s1\', []):\n    all_metrics.append({**m, \'scenario\': config.SCENARIO_SELECTED, \'model_type\': \'ANN_Cluster_S1\'})\n\ndf_ann_cmp = pd.DataFrame(all_metrics)\nprint("ANN REGRESSION MODEL EVALUATION TABLE:")\nprint(df_ann_cmp[[\'label\', \'model_type\', \'scenario\', \'n_obs\', \'rmse\', \'mae\', \'nsc\', \'r2\']].to_string(index=False))\n\ndf_ann_cmp.to_csv(REPORT_EVALUATION / \'ann_feature_comparison.csv\', index=False)\nprint(f"\\n[OK] ANN evaluation table saved: {REPORT_EVALUATION / \'ann_feature_comparison.csv\'}")\n', cell_id='ed2130be'),
