    md('## 9.5 K-Means Comparison'),
    code('km_all_csv = REPORT_CLUSTERING / \'kmeans_k_search_all_features.csv\'\nkm_sel_csv = REPORT_CLUSTERING / \'kmeans_k_search_selected_features.csv\'\n\nif km_all_csv.exists() and km_sel_csv.exists():\n    km_all = pd.read_csv(km_all_csv)\n    km_sel = pd.read_csv(km_sel_csv)\n\n    with open(DATA_INTERIM / \'kmeans_final.json\') as f:\n        km_final = json.load(f)\n\n    k_all = km_final[\'K_final_all\']\n    k_sel = km_final[\'K_final_selected\']\n\n    row_all = km_all[km_all[\'K\'] == k_all].iloc[0].to_dict()\n    row_sel = km_sel[km_sel[\'K\'] == k_sel].iloc[0].to_dict()\n    row_all[\'scenario\'] = config.SCENARIO_ALL\n    row_sel[\'scenario\'] = config.SCENARIO_SELECTED\n\n    df_km_cmp = pd.DataFrame([row_all, row_sel])\n    df_km_cmp.to_csv(REPORT_EVALUATION / \'kmeans_feature_comparison.csv\', index=False)\n    print("KMEANS FEATURE COMPARISON:")\n    print(df_km_cmp[[\'scenario\', \'K\', \'silhouette\', \'dbi\', \'chi\', \'inertia\']].to_string(index=False))\n', cell_id='8f642642'),
    md('## 9.6 Visual Comparison of Model Predictions & Residuals'),
    code('# =============================================================================\n# VISUALISASI PERBANDINGAN LENGKAP: ANN REGRESSION & K-MEANS (S0 vs S1)\n# =============================================================================\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport numpy as np\n\nplt.rcParams.update({\n    \'font.family\': \'DejaVu Sans\',\n    \'axes.spines.top\': False,\n    \'axes.spines.right\': False,\n    \'axes.grid\': True,\n    \'grid.alpha\': 0.35,\n    \'grid.linestyle\': \'--\',\n})\n\nCOLOR_S0 = \'#1565C0\'  # S0 All Features (Biru)\nCOLOR_S1 = \'#E64A19\'  # S1 Selected Features (Oranye)\nPALETTE = [COLOR_S0, COLOR_S1]\n\n# =============================================================================\n# 1. VISUALISASI METRIK PERBANDINGAN ANN REGRESSION (S0 vs S1) - Skala Fokus\n# =============================================================================\nr2_s0_val = float(df_ann_cmp[df_ann_cmp[\'label\'] == \'ANN_Global_S0\'][\'r2\'].values[0])\nr2_s1_val = float(df_ann_cmp[df_ann_cmp[\'label\'] == \'ANN_Global_S1\'][\'r2\'].values[0])\nrmse_s0_val = float(df_ann_cmp[df_ann_cmp[\'label\'] == \'ANN_Global_S0\'][\'rmse\'].values[0])\nrmse_s1_val = float(df_ann_cmp[df_ann_cmp[\'label\'] == \'ANN_Global_S1\'][\'rmse\'].values[0])\nmae_s0_val = float(df_ann_cmp[df_ann_cmp[\'label\'] == \'ANN_Global_S0\'][\'mae\'].values[0])\nmae_s1_val = float(df_ann_cmp[df_ann_cmp[\'label\'] == \'ANN_Global_S1\'][\'mae\'].values[0])\n\nANN_LABELS = [\'All Features (S0)\', \'Selected Features (S1)\']\n\nfig_ann, axes_ann = plt.subplots(1, 3, figsize=(16, 5.5), facecolor=\'#FAFAFA\')\n\n# Panel A: R2 Focused Scale\nax_r2 = axes_ann[0]\nax_r2.set_facecolor(\'#FFFFFF\')\nbars_r2 = ax_r2.bar(ANN_LABELS, [r2_s0_val, r2_s1_val], color=PALETTE, width=0.48,\n                     edgecolor=\'black\', linewidth=1.2, zorder=3)\ny_r2_lo = min(r2_s0_val, r2_s1_val) - 0.002\ny_r2_hi = max(r2_s0_val, r2_s1_val) + 0.003\nax_r2.set_ylim(y_r2_lo, y_r2_hi)\nax_r2.yaxis.set_major_formatter(plt.FuncFormatter(lambda y, _: f"{y*100:.2f}%"))\nax_r2.set_title(\'A. Koefisien Determinasi ($R^2$)\\n[Skala Fokus]\', fontsize=11, fontweight=\'bold\', pad=10)\nax_r2.set_ylabel(\'$R^2$ (%)\', fontsize=10)\nfor bar, val in zip(bars_r2, [r2_s0_val, r2_s1_val]):\n    h = bar.get_height()\n    ax_r2.annotate(f"{val*100:.4f}%", xy=(bar.get_x() + bar.get_width()/2, h),\n                   xytext=(0, 6), textcoords="offset points", ha=\'center\', va=\'bottom\',\n                   fontsize=10, fontweight=\'bold\',\n                   bbox=dict(boxstyle="round,pad=0.2", facecolor="white", edgecolor="#BDBDBD", alpha=0.9))\ndiff_r2 = (r2_s1_val - r2_s0_val) * 100\nax_r2.annotate(f"+{diff_r2:.4f}%\\n(S1 Lebih Baik)", xy=(1, r2_s1_val),\n               xytext=(0.48, r2_s1_val + 0.001),\n               arrowprops=dict(arrowstyle="->", color="#2E7D32", lw=1.8),\n               fontsize=8.5, fontweight=\'bold\', color="#2E7D32",\n               bbox=dict(boxstyle="round,pad=0.2", facecolor="#E8F8F5", edgecolor="#2E7D32"))\n\n# Panel B: RMSE Focused Scale\nax_rmse = axes_ann[1]\nax_rmse.set_facecolor(\'#FFFFFF\')\nbars_rmse = ax_rmse.bar(ANN_LABELS, [rmse_s0_val, rmse_s1_val], color=PALETTE, width=0.48,\n                         edgecolor=\'black\', linewidth=1.2, zorder=3)\ny_rmse_lo = min(rmse_s0_val, rmse_s1_val) - 0.15\ny_rmse_hi = max(rmse_s0_val, rmse_s1_val) + 0.15\nax_rmse.set_ylim(y_rmse_lo, y_rmse_hi)\nax_rmse.set_title(\'B. Root Mean Squared Error (RMSE)\\n[Skala Fokus]\', fontsize=11, fontweight=\'bold\', pad=10)\nax_rmse.set_ylabel(\'RMSE ($m^3$)\', fontsize=10)\nfor bar, val in zip(bars_rmse, [rmse_s0_val, rmse_s1_val]):\n    h = bar.get_height()\n    ax_rmse.annotate(f"{val:.4f} $m^3$", xy=(bar.get_x() + bar.get_width()/2, h),\n                     xytext=(0, 6), textcoords="offset points", ha=\'center\', va=\'bottom\',\n                     fontsize=10, fontweight=\'bold\',\n                     bbox=dict(boxstyle="round,pad=0.2", facecolor="white", edgecolor="#BDBDBD", alpha=0.9))\ndiff_rmse = rmse_s0_val - rmse_s1_val\nax_rmse.annotate(f"-{diff_rmse:.4f} $m^3$\\n(S1 Error Lebih Kecil)", xy=(1, rmse_s1_val),\n                 xytext=(0.38, rmse_s1_val + 0.06),\n                 arrowprops=dict(arrowstyle="->", color="#2E7D32", lw=1.8),\n                 fontsize=8.5, fontweight=\'bold\', color="#2E7D32",\n                 bbox=dict(boxstyle="round,pad=0.2", facecolor="#E8F8F5", edgecolor="#2E7D32"))\n\n# Panel C: MAE Focused Scale\nax_mae = axes_ann[2]\nax_mae.set_facecolor(\'#FFFFFF\')\nbars_mae = ax_mae.bar(ANN_LABELS, [mae_s0_val, mae_s1_val], color=PALETTE, width=0.48,\n                       edgecolor=\'black\', linewidth=1.2, zorder=3)\ny_mae_lo = min(mae_s0_val, mae_s1_val) - 0.05\ny_mae_hi = max(mae_s0_val, mae_s1_val) + 0.06\nax_mae.set_ylim(y_mae_lo, y_mae_hi)\nax_mae.set_title(\'C. Mean Absolute Error (MAE)\\n[Skala Fokus]\', fontsize=11, fontweight=\'bold\', pad=10)\nax_mae.set_ylabel(\'MAE ($m^3$)\', fontsize=10)\nfor bar, val in zip(bars_mae, [mae_s0_val, mae_s1_val]):\n    h = bar.get_height()\n    ax_mae.annotate(f"{val:.4f} $m^3$", xy=(bar.get_x() + bar.get_width()/2, h),\n                    xytext=(0, 6), textcoords="offset points", ha=\'center\', va=\'bottom\',\n                    fontsize=10, fontweight=\'bold\',\n                    bbox=dict(boxstyle="round,pad=0.2", facecolor="white", edgecolor="#BDBDBD", alpha=0.9))\ndiff_mae = mae_s1_val - mae_s0_val\ndirection_mae = "Sedikit Lebih Tinggi" if diff_mae > 0 else "Lebih Rendah"\nax_mae.text(0.5, 0.85, f"Selisih MAE: {abs(diff_mae):.4f} $m^3$\\n({direction_mae})",\n            transform=ax_mae.transAxes, ha=\'center\', fontsize=9, fontweight=\'bold\', color=\'#1565C0\',\n            bbox=dict(boxstyle="round,pad=0.25", facecolor="#E3F2FD", edgecolor="#1565C0"))\n\nplt.suptitle(\'Evaluasi ANN Regression: All Features (S0) vs Selected Features (S1)\',\n             fontsize=13.5, fontweight=\'bold\', y=0.995)\nplt.tight_layout()\nann_cmp_fig = REPORT_EVALUATION / \'ann_feature_comparison.png\'\nplt.savefig(ann_cmp_fig, dpi=200, bbox_inches=\'tight\', facecolor=\'#FAFAFA\')\nplt.show()\nprint(f"[OK] ANN Regression comparison plot saved: {ann_cmp_fig}")\n\n# =============================================================================\n# 2. VISUALISASI METRIK PERBANDINGAN CLUSTERING K-MEANS (S0 vs S1)\n# =============================================================================\nif \'df_km_cmp\' in locals() and len(df_km_cmp) >= 2:\n    row_all = df_km_cmp[df_km_cmp[\'scenario\'] == \'S0_ALL_FEATURES\'].iloc[0]\n    row_sel = df_km_cmp[df_km_cmp[\'scenario\'] == \'S1_SELECTED_FEATURES\'].iloc[0]\n    k_all = int(row_all[\'K\'])\n    k_sel = int(row_sel[\'K\'])\n\n    fig_km, axes_km = plt.subplots(1, 3, figsize=(16, 5.5), facecolor=\'#FAFAFA\')\n    km_metrics = [\'silhouette\', \'dbi\', \'chi\']\n    km_titles = [\n        \'A. Silhouette Score\\n(Tinggi Lebih Baik)\',\n        \'B. Davies-Bouldin Index\\n(Rendah Lebih Baik)\',\n        \'C. Calinski-Harabasz Index\\n(Tinggi Lebih Baik)\'\n    ]\n    km_ylabels = [\'Silhouette Score\', \'DBI Score\', \'CHI Score\']\n    KM_PALETTE = [\'#1565C0\', \'#43A047\']\n\n    for ax, m, t, yl in zip(axes_km, km_metrics, km_titles, km_ylabels):\n        ax.set_facecolor(\'#FFFFFF\')\n        v_s0 = float(row_all[m])\n        v_s1 = float(row_sel[m])\n        lbls = [f"S0: All Features\\n(K={k_all})", f"S1: Selected Features\\n(K={k_sel})"]\n        vals = [v_s0, v_s1]\n\n        bars = ax.bar(lbls, vals, color=KM_PALETTE, width=0.48, edgecolor=\'black\', linewidth=1.1, alpha=0.9, zorder=3)\n\n        if m == \'silhouette\':\n            ax.set_ylim(0.90, 0.96)\n        elif m == \'dbi\':\n            ax.set_ylim(0, 0.45)\n        elif m == \'chi\':\n            ax.set_ylim(0, 1050000)\n            ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda y, _: f"{y:,.0f}"))\n\n        for bar, val in zip(bars, vals):\n            h = bar.get_height()\n            txt = f"{val:.4f}" if m != \'chi\' else f"{val:,.1f}"\n            ax.annotate(\n                txt,\n                xy=(bar.get_x() + bar.get_width() / 2, h),\n                xytext=(0, 4), textcoords="offset points",\n                ha=\'center\', va=\'bottom\', fontsize=10, fontweight=\'bold\',\n                bbox=dict(boxstyle="round,pad=0.2", facecolor="white", alpha=0.85, edgecolor="#BDBDBD")\n            )\n\n        if m == \'dbi\':\n            pct_change = ((v_s1 - v_s0) / v_s0) * 100\n            ax.text(0.5, 0.85, f"DBI Improvement: {pct_change:.1f}%\\n(S1 Clusters more separated)",\n                    transform=ax.transAxes, ha=\'center\', fontsize=9, fontweight=\'bold\', color=\'#2E7D32\',\n                    bbox=dict(boxstyle="round,pad=0.3", facecolor="#E8F8F5", edgecolor="#2E7D32"))\n        elif m == \'silhouette\':\n            ax.text(0.5, 0.85, f"Peningkatan: +{v_s1 - v_s0:.4f}\\n(Kepadatan klaster terjaga)",\n                    transform=ax.transAxes, ha=\'center\', fontsize=9, fontweight=\'bold\', color=\'#1565C0\',\n                    bbox=dict(boxstyle="round,pad=0.3", facecolor="#E3F2FD", edgecolor="#1565C0"))\n\n        ax.set_title(t, fontsize=10.5, fontweight=\'bold\', pad=8)\n        ax.set_ylabel(yl, fontsize=10)\n        ax.grid(axis=\'y\', linestyle=\':\', alpha=0.6, zorder=0)\n\n    plt.suptitle(\'Evaluasi Komparatif Klastering K-Means: S0 (All Features) vs S1 (Selected Features)\',\n                 fontsize=12.5, fontweight=\'bold\', y=0.995)\n    plt.tight_layout()\n    km_cmp_fig = REPORT_EVALUATION / \'kmeans_feature_comparison.png\'\n    plt.savefig(km_cmp_fig, dpi=200, bbox_inches=\'tight\', facecolor=\'#FAFAFA\')\n    plt.show()\n    print(f"[OK] Grafik perbandingan K-Means disimpan: {km_cmp_fig}")\n\n# =============================================================================\n# 3. VISUALISASI KOMPARASI OUTPUT PREDIKSI: ANN REGRESSION S0 vs S1\n# =============================================================================\ny_true = df_test_valid[TARGET].values\nmask = ~(np.isnan(y_true) | np.isnan(y_pred_s0) | np.isnan(y_pred_s1))\nyt = y_true[mask]\nyp_s0 = y_pred_s0[mask]\nyp_s1 = y_pred_s1[mask]\n\nfig, axes = plt.subplots(2, 2, figsize=(15, 12), facecolor=\'#FAFAFA\')\np99 = max(float(np.percentile(yt, 99)), float(np.percentile(yp_s1, 99)), 50.0)\n\n# Subplot 1: S0 All Features Actual vs Pred\nax1 = axes[0, 0]\nax1.set_facecolor(\'#FFFFFF\')\nhb0 = ax1.hexbin(yt, yp_s0, gridsize=45, cmap="Blues", mincnt=1, extent=[0, p99, 0, p99])\nfig.colorbar(hb0, ax=ax1, label="Customer Count")\nax1.plot([0, p99], [0, p99], color="#D32F2F", linestyle="--", linewidth=2, label="Ideal (y = x)")\nax1.set_xlim(0, p99)\nax1.set_ylim(0, p99)\nax1.set_title("A. Actual vs Predicted: ANN Regression S0 (All Features)", fontsize=11.5, fontweight="bold")\nax1.set_xlabel("Actual Usage ($m^3$)")\nax1.set_ylabel("Predicted Usage ($m^3$)")\nax1.text(0.05, 0.78, f"$R^2$ = {r2_s0_val*100:.2f}%\\nMAE = {mae_s0_val:.2f} $m^3$\\nRMSE = {rmse_s0_val:.2f} $m^3$",\n         transform=ax1.transAxes, fontsize=9.5, fontweight=\'bold\',\n         bbox=dict(boxstyle="round,pad=0.4", facecolor="#E3F2FD", alpha=0.9, edgecolor="#1976D2"))\nax1.legend(loc="lower right")\nax1.grid(True, linestyle=":", alpha=0.5)\n\n# Subplot 2: S1 Selected Features Actual vs Pred\nax2 = axes[0, 1]\nax2.set_facecolor(\'#FFFFFF\')\nhb1 = ax2.hexbin(yt, yp_s1, gridsize=45, cmap="Oranges", mincnt=1, extent=[0, p99, 0, p99])\nfig.colorbar(hb1, ax=ax2, label="Customer Count")\nax2.plot([0, p99], [0, p99], color="#D32F2F", linestyle="--", linewidth=2, label="Ideal (y = x)")\nax2.set_xlim(0, p99)\nax2.set_ylim(0, p99)\nax2.set_title("B. Actual vs Predicted: ANN Regression S1 (Selected Features)", fontsize=11.5, fontweight="bold")\nax2.set_xlabel("Actual Usage ($m^3$)")\nax2.set_ylabel("Predicted Usage ($m^3$)")\nax2.text(0.05, 0.78, f"$R^2$ = {r2_s1_val*100:.2f}%\\nMAE = {mae_s1_val:.2f} $m^3$\\nRMSE = {rmse_s1_val:.2f} $m^3$",\n         transform=ax2.transAxes, fontsize=9.5, fontweight=\'bold\',\n         bbox=dict(boxstyle="round,pad=0.4", facecolor="#FFF3E0", alpha=0.9, edgecolor="#FB8C00"))\nax2.legend(loc="lower right")\nax2.grid(True, linestyle=":", alpha=0.5)\n\n# Subplot 3: Residual Distribution Comparison (S0 vs S1)\nax3 = axes[1, 0]\nax3.set_facecolor(\'#FFFFFF\')\nres_s0 = yt - yp_s0\nres_s1 = yt - yp_s1\nres_s0_clean = res_s0[np.abs(res_s0) <= np.percentile(np.abs(res_s0), 99)]\nres_s1_clean = res_s1[np.abs(res_s1) <= np.percentile(np.abs(res_s1), 99)]\n\nax3.hist(res_s0_clean, bins=50, color=\'#1565C0\', alpha=0.5, density=True, label=\'Residual S0 (All Features)\')\nax3.hist(res_s1_clean, bins=50, color=\'#E64A19\', alpha=0.5, density=True, label=\'Residual S1 (Selected Features)\')\nax3.axvline(0, color=\'red\', linestyle=\'--\', linewidth=1.5, label=\'Zero Error\')\nax3.set_title("C. Residual Error Distribution: ANN Regression S0 vs S1", fontsize=11.5, fontweight="bold")\nax3.set_xlabel("Prediction Error / Residual ($m^3$)")\nax3.set_ylabel("Probability Density")\nax3.legend()\nax3.grid(True, linestyle=":", alpha=0.5)\n\n# Subplot 4: Sample Time-Series Tracking (Actual vs S0 vs S1)\nax4 = axes[1, 1]\nax4.set_facecolor(\'#FFFFFF\')\nnp.random.seed(42)\nsample_pts = np.random.choice(len(yt), size=50, replace=False)\nsample_pts = np.sort(sample_pts)\nx_idx = np.arange(len(sample_pts))\n\nax4.plot(x_idx, yt[sample_pts], \'k-o\', label=\'Actual Usage\', linewidth=2, markersize=5)\nax4.plot(x_idx, yp_s0[sample_pts], \'s--\', color=\'#1565C0\', label=\'ANN Regression S0 (All Features)\', linewidth=1.8, markersize=4)\nax4.plot(x_idx, yp_s1[sample_pts], \'^:\', color=\'#E64A19\', label=\'ANN Regression S1 (Selected Features)\', linewidth=1.8, markersize=4)\nax4.set_title("D. Time-Series Tracking on Test Customer Sample", fontsize=11.5, fontweight="bold")\nax4.set_xlabel("Sample Test Index")\nax4.set_ylabel("Water Consumption ($m^3$)")\nax4.legend()\nax4.grid(True, linestyle=":", alpha=0.5)\n\nplt.suptitle(\'ANN Regression Prediction Output Evaluation:\\nS0 (All Features) vs S1 (Selected Features)\',\n             fontsize=13.5, fontweight="bold", y=0.995)\nplt.tight_layout()\nann_out_fig = REPORT_EVALUATION / \'ann_regression_prediction_outputs.png\'\nplt.savefig(ann_out_fig, dpi=200, bbox_inches=\'tight\', facecolor=\'#FAFAFA\')\nplt.show()\nprint(f"[OK] ANN Regression prediction visualization saved: {ann_out_fig}")\n', cell_id='faefd36f'),
