nb11 = make_nb([
    md('# Notebook 11 — Interactive Geospatial Web-GIS Map for PDAM (Dual Model: K-Means Clustering + ANN Spike Detection)\n**CRISP-DM Phase:** Deployment\n\n> Interactive Folium Web-GIS platform mapping 24,187 customer meters across Purbalingga Regency.\n> Features:\n> 1. Multi-layer satellite and cartographic basemaps.\n> 2. K-Means customer segmentation clustering (K=3).\n> 3. ANN regression demand predictions and anomaly detection flags.\n> 4. In-popup SVG dynamic 12-period consumption trend sparklines.'),
    md('## 11.1 Setup Environment, Paths & Libraries'),
    code("import sys, warnings, os\nfrom pathlib import Path\nsys.path.insert(0, '..')\nwarnings.filterwarnings('ignore')\n\nimport pandas as pd\nimport numpy as np\nimport json\nimport folium\nfrom folium.plugins import MarkerCluster, Fullscreen\nfrom IPython.display import display, HTML, IFrame\n\n# Robust Path Resolution (Kompatibel Jupyter Notebook & Eksekusi Skrip)\nCURRENT_DIR = Path('.').resolve()\nBASE_DIR = CURRENT_DIR.parent if CURRENT_DIR.name == 'notebooks' else CURRENT_DIR\nPROJECT_ROOT = BASE_DIR\nDATA_PROCESSED = BASE_DIR / 'data' / 'processed'\nDATA_INTERIM = BASE_DIR / 'data' / 'interim'\nOUTPUT_SPIKE = BASE_DIR / 'outputs' / 'spike_detection'\nOUTPUT_MAPS = BASE_DIR / 'outputs' / 'maps'\nOUTPUT_CLUST_SEL = BASE_DIR / 'outputs' / 'clustering' / 'selected_features'\nOUTPUT_CLUST_ALL = BASE_DIR / 'outputs' / 'clustering' / 'all_features'\n\nOUTPUT_MAPS.mkdir(parents=True, exist_ok=True)\nprint('[OK] Libraries and directory configurations initialized successfully.')\nprint(f'     Base Directory:    {BASE_DIR}')\nprint(f'     Clustering Output: {OUTPUT_CLUST_SEL}')\nprint(f'     Output Maps:       {OUTPUT_MAPS}')\n"),
    md('## 11.2 Load Master Features, K-Means Segmentation, & ANN Prediction Reports\n\n> Load PDAM Purbalingga customer master data across all 5 operational branches, integrating:\n> 1. **K-Means Segmentation ($K=3$)**: Customer behavioral consumption profiling.\n> 2. **ANN Regression Model**: Predicted next-period consumption volume and spike anomaly status.\n> 3. **Customer Key Normalization**: Synchronizing 8-digit zero-padded NoPEL strings across datasets.'),
    code("# ===============================================================\n# 1. Load Master Dataset & Detailed Customer Attributes\n# ===============================================================\nif 'BASE_DIR' not in globals():\n    from pathlib import Path\n    _c = Path('.').resolve()\n    BASE_DIR = _c.parent if _c.name == 'notebooks' else _c\n    DATA_PROCESSED = BASE_DIR / 'data' / 'processed'\n    OUTPUT_SPIKE = BASE_DIR / 'outputs' / 'spike_detection'\n    OUTPUT_CLUST_SEL = BASE_DIR / 'outputs' / 'clustering' / 'selected_features'\n    OUTPUT_CLUST_ALL = BASE_DIR / 'outputs' / 'clustering' / 'all_features'\n    OUTPUT_MAPS = BASE_DIR / 'outputs' / 'maps'\n\ndf = pd.read_parquet(DATA_PROCESSED / 'master_features.parquet')\n\n# Ensure numeric coordinate columns & 8-digit NoPEL\nif 'latitude' not in df.columns and 'lati' in df.columns:\n    df['latitude'] = pd.to_numeric(df['lati'], errors='coerce')\nif 'longitude' not in df.columns and 'longi' in df.columns:\n    df['longitude'] = pd.to_numeric(df['longi'], errors='coerce')\nif 'usage_current' not in df.columns and 'Ini' in df.columns and 'Lalu' in df.columns:\n    df['usage_current'] = pd.to_numeric(df['Ini'], errors='coerce') - pd.to_numeric(df['Lalu'], errors='coerce')\n\ndf['NoPEL'] = df['NoPEL'].astype(str).str.zfill(8)\nprint(f'[INFO] Master features loaded: {len(df):,} records')\n\n# Load informasi tarif dari master_clean (tarif_symbol & tarif_name)\nclean_cols = ['NoPEL', 'tarif_symbol', 'tarif_name']\ndf_clean_info = pd.read_parquet(DATA_PROCESSED / 'master_clean.parquet', columns=clean_cols)\ndf_clean_info['NoPEL'] = df_clean_info['NoPEL'].astype(str).str.zfill(8)\ndf_clean_info = df_clean_info.drop_duplicates(subset=['NoPEL'], keep='last')\n\n# ===============================================================\n# 2. Extract Recent Valid GPS Coordinates per NoPEL\n# ===============================================================\ndf_valid_geo = df[\n    df['latitude'].notna() & df['longitude'].notna() &\n    (df['latitude'] != 0) & (df['longitude'] != 0) &\n    (df['latitude'].between(-7.6, -7.1)) &\n    (df['longitude'].between(109.1, 109.6))\n]\n\ncust_coords = df_valid_geo.groupby('NoPEL')[['latitude', 'longitude']].last().reset_index()\nprint(f'[INFO] Customers with valid Purbalingga coordinates: {len(cust_coords):,} NoPEL')\n\n# Customer identity metadata (NoPEL, Alamat, RAYON, tarif)\nmeta_cols = [c for c in ['NoPEL', 'Alamat', 'RAYON', 'tarif', 'usage_current'] if c in df.columns]\ncust_meta = df[meta_cols].drop_duplicates(subset=['NoPEL'], keep='last')\n\ncust_geo = cust_coords.merge(cust_meta, on='NoPEL', how='left')\ncust_geo = cust_geo.merge(df_clean_info, on='NoPEL', how='left')\n\n# ===============================================================\n# 3. Integrate K-Means Clustering Model\n# ===============================================================\nclust_file = OUTPUT_CLUST_SEL / 'customer_clusters.parquet'\nif not clust_file.exists():\n    clust_file = OUTPUT_CLUST_ALL / 'customer_clusters.parquet'\n\nif clust_file.exists():\n    df_clust = pd.read_parquet(clust_file)\n    df_clust['NoPEL'] = df_clust['NoPEL'].astype(str).str.zfill(8)\n    print(f'[INFO] K-Means cluster data loaded: {len(df_clust):,} customers')\n    cust_geo = cust_geo.merge(df_clust[['NoPEL', 'cluster_id', 'cluster_label']].drop_duplicates('NoPEL'), on='NoPEL', how='left')\n    cust_geo['cluster_id'] = cust_geo['cluster_id'].fillna(1).astype(int)\n    label_map = {0: 'Cluster 0 (LOW)', 1: 'Cluster 1 (MEDIUM)', 2: 'Cluster 2 (HIGH)'}\n    cust_geo['cluster_label'] = cust_geo['cluster_id'].map(label_map).fillna('Cluster 1 (MEDIUM)')\nelse:\n    cust_geo['cluster_id'] = 1\n    cust_geo['cluster_label'] = 'Cluster 1 (MEDIUM)'\n\n# ===============================================================\n# 4. Integrate ANN Regression Model (Predictions & Spike Status)\n# ===============================================================\nspike_csv = OUTPUT_SPIKE / 'spike_detection_report.csv'\nif spike_csv.exists():\n    spike_report = pd.read_csv(spike_csv)\n    spike_report['NoPEL'] = spike_report['NoPEL'].astype(str).str.zfill(8)\n    spike_latest = spike_report[['NoPEL', 'actual', 'prediction', 'pct_diff', 'spike_status']].groupby('NoPEL').last().reset_index()\n    print(f'[INFO] ANN prediction & spike report loaded: {len(spike_latest):,} customers')\n    cust_geo = cust_geo.merge(spike_latest, on='NoPEL', how='left')\n    cust_geo['spike_status'] = cust_geo['spike_status'].fillna('NORMAL')\n    cust_geo['actual'] = cust_geo['actual'].fillna(cust_geo['usage_current']).fillna(0.0)\n    cust_geo['prediction'] = cust_geo['prediction'].fillna(cust_geo['actual']).fillna(0.0)\n    cust_geo['pct_diff'] = cust_geo['pct_diff'].fillna(0.0)\nelse:\n    cust_geo['spike_status'] = 'NORMAL'\n    cust_geo['actual'] = cust_geo['usage_current'].fillna(0.0)\n    cust_geo['prediction'] = cust_geo['actual']\n    cust_geo['pct_diff'] = 0.0\n\nprint('=' * 60)\nprint(f'[OK] Total Mapped Customers in Purbalingga: {len(cust_geo):,} customers')\nprint('=' * 60)\nprint('K-Means Customer Segmentation Distribution:')\nprint(cust_geo['cluster_label'].value_counts().to_string())\nprint('\\nANN Regression & Spike Anomaly Status Distribution:')\nprint(cust_geo['spike_status'].value_counts().to_string())\n"),
    md('## 11.3 Extract 12-Period Consumption History & In-Popup SVG Chart Generator'),
    code('# ===============================================================\n# Extract 12-period consumption history per NoPEL\n# ===============================================================\ndf_sorted = df.sort_values([\'NoPEL\', \'period_dt\'])\nrecent_usage = df_sorted.groupby(\'NoPEL\')[\'usage_current\'].apply(lambda s: s.dropna().tail(12).tolist()).to_dict()\n\n# Extract period labels for X-axis sparkline (format YYYY-MM)\ndef get_period_labels(grp):\n    return grp.dropna().tail(12).dt.strftime(\'%Y-%m\').tolist()\n\nrecent_periods = df_sorted.groupby(\'NoPEL\')[\'period_dt\'].apply(get_period_labels).to_dict()\n\ndef generate_svg_chart(history_vals, period_labels=None):\n    """\n    Generate 12-period SVG sparkline chart for embedding inside marker popup cards.\n    Format:\n    - Garis biru solid + titik biru: Nilai konsumsi aktual historis bulanan\n    - Garis oranye putus-putus: Rata-rata / batas ambang konsumsi\n    - Label periode pada sumbu horizontal\n    """\n    if len(history_vals) < 2:\n        return "<div style=\'color:grey;font-size:10px;padding:4px;\'>Limited historical records</div>"\n    \n    vals = [float(v) for v in history_vals[-12:]]\n    max_val = max(max(vals), 1.0)\n    avg_val = np.mean(vals)\n    thresh_val = avg_val * 1.3\n    max_scale = max(max_val, thresh_val) * 1.15\n    \n    w, h = 260, 95\n    pad_left, pad_right, pad_top, pad_bottom = 20, 10, 15, 20\n    \n    n = len(vals)\n    pts = []\n    th_pts = []\n    \n    for i, val in enumerate(vals):\n        x = pad_left + (i / (n - 1)) * (w - pad_left - pad_right)\n        y = pad_top + (1 - val / max_scale) * (h - pad_top - pad_bottom)\n        pts.append((x, y))\n        \n        # Garis ambang batas oranye\n        y_th = pad_top + (1 - thresh_val / max_scale) * (h - pad_top - pad_bottom)\n        th_pts.append((x, y_th))\n    \n    pts_str = \' \'.join([f\'{p[0]:.1f},{p[1]:.1f}\' for p in pts])\n    th_pts_str = \' \'.join([f\'{p[0]:.1f},{p[1]:.1f}\' for p in th_pts])\n    \n    # Dots data aktual (biru) dan ambang (oranye)\n    dots_blue = \'\'.join([f\'<circle cx="{p[0]:.1f}" cy="{p[1]:.1f}" r="2.5" fill="#1976D2"/>\' for p in pts])\n    dots_orange = \'\'.join([f\'<circle cx="{p[0]:.1f}" cy="{p[1]:.1f}" r="2" fill="#FB8C00"/>\' for p in th_pts])\n    \n    # Label sumbu X (tampilkan 3 periode: awal, tengah, akhir)\n    x_labels = \'\'\n    if period_labels and len(period_labels) >= 2:\n        plabels = period_labels[-n:]\n        indices = [0, len(plabels) // 2, len(plabels) - 1]\n        for idx in sorted(list(set(indices))):\n            if idx < len(plabels):\n                x = pad_left + (idx / (n - 1)) * (w - pad_left - pad_right)\n                align = "start" if idx == 0 else ("end" if idx == len(plabels) - 1 else "middle")\n                x_labels += f\'<text x="{x}" y="{h-4}" font-size="7.5" fill="#757575" font-family="Arial,sans-serif" text-anchor="{align}">{plabels[idx]}</text>\'\n    \n    svg = f"""\n    <svg width="{w}" height="{h}" style="background:#ffffff; border:1px solid #e0e0e0; border-radius:3px; margin-top:4px;">\n        <line x1="{pad_left}" y1="{pad_top}" x2="{w-pad_right}" y2="{pad_top}" stroke="#f5f5f5" stroke-width="1"/>\n        <line x1="{pad_left}" y1="{h-pad_bottom}" x2="{w-pad_right}" y2="{h-pad_bottom}" stroke="#e0e0e0" stroke-width="1"/>\n        <polyline fill="none" stroke="#FB8C00" stroke-width="1.8" stroke-dasharray="3,3" points="{th_pts_str}" />\n        {dots_orange}\n        <polyline fill="none" stroke="#1976D2" stroke-width="2" points="{pts_str}" />\n        {dots_blue}\n        {x_labels}\n    </svg>\n    """\n    return svg\n\nprint(f\'[OK] 12-period consumption history extracted for {len(recent_usage):,} customers.\')\nprint(\'[OK] In-popup SVG chart generator ready for deployment.\')\n'),
    md('## 11.4 Initialize Folium Map with Base Layers, Compass, & Legends'),
    code('# ===============================================================\n# Initialize Folium Map\n# ===============================================================\ncenter_lat = cust_geo[\'latitude\'].median()\ncenter_lon = cust_geo[\'longitude\'].median()\n\npdam_map = folium.Map(\n    location=[center_lat, center_lon],\n    zoom_start=13,\n    tiles=None,\n    control_scale=True\n)\n\n# Base Map Layers\nfolium.TileLayer(\n    tiles=\'https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}\',\n    attr=\'Google Hybrid Satellite\',\n    name=\'Google Hybrid Satellite\',\n    overlay=False,\n    control=True\n).add_to(pdam_map)\n\nfolium.TileLayer(\n    tiles=\'OpenStreetMap\',\n    name=\'OpenStreetMap\',\n    overlay=False,\n    control=True\n).add_to(pdam_map)\n\nfolium.TileLayer(\n    tiles=\'CartoDB positron\',\n    name=\'Light Map\',\n    overlay=False,\n    control=True\n).add_to(pdam_map)\n\n# ===============================================================\n# Compass Rose - N/S/E/W Circular Badge\n# ===============================================================\ncompass_html = """\n<div style="position: fixed; \n     top: 75px; left: 15px; width: 55px; height: 55px; \n     z-index:9999; background: rgba(255,255,255,0.95); border: 2px solid #37474F; border-radius: 50%;\n     display: flex; align-items: center; justify-content: center;\n     box-shadow: 0 2px 6px rgba(0,0,0,0.3); font-family: Arial, sans-serif;">\n     <svg width="45" height="45" viewBox="0 0 100 100">\n        <circle cx="50" cy="50" r="46" fill="none" stroke="#37474F" stroke-width="2"/>\n        <text x="50" y="24" text-anchor="middle" font-size="20" font-weight="bold" fill="#D32F2F">N</text>\n        <text x="50" y="88" text-anchor="middle" font-size="18" font-weight="bold" fill="#37474F">S</text>\n        <text x="82" y="56" text-anchor="middle" font-size="18" font-weight="bold" fill="#37474F">E</text>\n        <text x="18" y="56" text-anchor="middle" font-size="18" font-weight="bold" fill="#37474F">W</text>\n     </svg>\n</div>\n"""\npdam_map.get_root().html.add_child(folium.Element(compass_html))\n\n# ===============================================================\n# Legenda K-Means Customer Segmentation (Persis Screenshot Referensi)\n# ===============================================================\nlegend_html = """\n<div style="position: fixed; \n     bottom: 30px; left: 15px; width: 220px;\n     border: 2px solid #37474F; z-index:9999; font-size:11px; font-family: Arial, sans-serif;\n     background-color: rgba(255,255,255,0.96); padding: 10px 12px; border-radius: 4px; \n     box-shadow: 0 2px 8px rgba(0,0,0,0.3);">\n     \n     <div style="font-weight: bold; margin-bottom: 6px; color: #111;">\n        K-Means Customer Segmentation\n     </div>\n     \n     <div style="line-height: 1.8;">\n        <span style="display:inline-block; width:10px; height:10px; background:#00BCD4; border-radius:50%; margin-right:6px;"></span>Cluster 0 (LOW)<br>\n        <span style="display:inline-block; width:10px; height:10px; background:#FFEB3B; border-radius:50%; margin-right:6px; border:1px solid #d4c000;"></span>Cluster 1 (MEDIUM)<br>\n        <span style="display:inline-block; width:10px; height:10px; background:#4CAF50; border-radius:50%; margin-right:6px;"></span>Cluster 2 (HIGH)\n     </div>\n     \n     <div style="margin-top: 8px; font-size: 10px; color: #555; line-height: 1.4;">\n        Click marker for 12-period trend<br>\n        Numeric tariff from billing records.\n     </div>\n</div>\n"""\npdam_map.get_root().html.add_child(folium.Element(legend_html))\n\nprint(\'[OK] Base map, compass rose, and legends successfully configured.\')\n'),
    md('## 11.5 Render Customer Meters & Interactive Popup Cards\n\nInteractive popup cards display:\n- **Customer ID (NoPEL)**\n- **Address (Alamat)**\n- **Branch / Rayon**\n- **Numeric Tariff**\n- **K-Means Cluster Assignment**\n- **ANN Predicted Demand** ($m^3$)\n- **Observed Actual Demand** ($m^3$)\n- **Prediction Residual Error** ($m^3$)\n- **Spike Anomaly Flag** (Normal, Low Anomaly, Spike Indication)\n- **12-Period Consumption Sparkline**'),
    code('# ===============================================================\n# Cluster segmentation colors matching K-Means legend\n# ===============================================================\ncluster_colors = {\n    0: \'#00BCD4\',  # Cyan / Biru Muda (RENDAH)\n    1: \'#FFEB3B\',  # Kuning / Oranye (SEDANG)\n    2: \'#4CAF50\',  # Hijau (TINGGI)\n}\n\ncustomer_layer = folium.FeatureGroup(name=\'All Customers (K-Means)\')\nmc = MarkerCluster(name=\'Customer Clusters\').add_to(customer_layer)\n\n# Render customer markers (representative 5,000 sample points for optimal browser performance)\nMAX_MARKERS = 5000\nis_sampled = len(cust_geo) > MAX_MARKERS\nsample_pts = cust_geo.sample(MAX_MARKERS, random_state=42) if is_sampled else cust_geo\n\nprint(f\'Markers: {len(sample_pts):,} | Sampling: {is_sampled} | Total mapped customers: {len(cust_geo):,}\')\nprint(f\'Rendering {len(sample_pts):,} PDAM customers on geospatial map...\')\n\ncount = 0\nfor _, row in sample_pts.iterrows():\n    cid = int(row[\'cluster_id\'])\n    dot_color = cluster_colors.get(cid, \'#00BCD4\')\n    nopel = str(row[\'NoPEL\'])\n\n    # 12-Period history & SVG Chart\n    hist_vals = recent_usage.get(nopel, [row.get(\'actual\', 0)])\n    period_labs = recent_periods.get(nopel, [])\n    chart_svg = generate_svg_chart(hist_vals, period_labs)\n\n    # Evaluate actual, predicted, and error values\n    actual_val = float(row.get(\'actual\', 0))\n    pred_val = float(row.get(\'prediction\', 0))\n    err_abs = abs(actual_val - pred_val)\n    spike_status = str(row.get(\'spike_status\', \'NORMAL\')).upper()\n\n    # Status color badge\n    if \'LONJAKAN\' in spike_status:\n        status_color = \'#C62828\'\n    elif \'RENDAH\' in spike_status or \'ANOMALI\' in spike_status:\n        status_color = \'#EF6C00\'\n    else:\n        status_color = \'#2E7D32\'\n\n    # Identity attributes\n    alamat_val = str(row.get(\'Alamat\', \'-\'))\n    if alamat_val.upper() in [\'NAN\', \'NONE\', \'\']:\n        alamat_val = \'-\'\n\n    rayon_val = str(row.get(\'RAYON\', \'-\'))\n    if rayon_val.upper() in [\'NAN\', \'NONE\', \'\']:\n        rayon_val = \'-\'\n\n    tarif_val = str(row.get(\'tarif_name\', \'\'))\n    if not tarif_val or tarif_val.upper() in [\'NAN\', \'NONE\', \'\']:\n        t_num = row.get(\'tarif\')\n        tarif_val = str(int(t_num)) if pd.notna(t_num) else \'10\'\n\n    cluster_label_val = str(row.get(\'cluster_label\', f\'Cluster {cid}\'))\n\n    # Numeric tariff\n    t_val = row.get(\'tarif\')\n    try:\n        tarif_num_str = str(int(round(float(t_val)))) if (pd.notna(t_val) and str(t_val).strip() != \'\') else \'-\'\n    except Exception:\n        tarif_num_str = \'-\'\n\n    # ===============================================================\n    # Clean Popup Card:\n    # 1. NoPEL     4. Tarif      7. Status     10. Error\n    # 2. Alamat    5. Cluster    8. Aktual     11. Grafik 12 Periode\n    # 3. Rayon     6. ANN Reg    9. Prediksi\n    # ===============================================================\n    popup_content = (\n        \'<div style="font-family: Arial, Helvetica, sans-serif; font-size: 11px; \'\n        \'line-height: 1.5; color: #212121; width: 275px; padding: 3px;">\'\n        \'<div style="font-weight: bold; font-size: 13px; margin-bottom: 6px; color: #0D47A1; \'\n        \'border-bottom: 1.5px solid #1976D2; padding-bottom: 3px;">PDAM Customer Details</div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Customer ID:</b> {nopel}</div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Address:</b> {alamat_val}</div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Branch / Rayon:</b> {rayon_val}</div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Numeric Tariff:</b> {tarif_num_str}</div>\'        f\'<div style="margin-top: 4px; margin-bottom: 4px;"><b>Cluster:</b> {cluster_label_val}</div>\'\n        \'<div style="margin-top: 6px; margin-bottom: 4px; font-weight: bold; color: #0D47A1; \'\n        \'border-top: 1px dashed #B0BEC5; padding-top: 4px;">ANN Regression</div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Status:</b> <span style="font-weight: bold; color: {status_color};">{spike_status}</span></div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Actual:</b> {actual_val:.2f} m&#179;</div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Predicted:</b> {pred_val:.2f} m&#179;</div>\'\n        f\'<div style="margin-bottom: 2px;"><b>Error:</b> {err_abs:.2f} m&#179;</div>\'\n        \'<div style="margin-top: 8px; margin-bottom: 2px; font-weight: bold; color: #212121;">\'\n        \'12-Period Consumption Trend</div>\'\n        f\'{chart_svg}\'\n        \'</div>\'\n    )\n\n    folium.CircleMarker(\n        location=[row[\'latitude\'], row[\'longitude\']],\n        radius=5,\n        color=\'#333333\' if dot_color == \'#FFEB3B\' else dot_color,\n        fill=True,\n        fill_color=dot_color,\n        fill_opacity=0.9,\n        weight=0.8,\n        popup=folium.Popup(popup_content, max_width=310),\n    ).add_to(mc)\n\n    count += 1\n    if count % 1000 == 0:\n        print(f\'  [INFO] Rendered {count:,} markers...\')\n\ncustomer_layer.add_to(pdam_map)\nfolium.LayerControl(collapsed=False).add_to(pdam_map)\nFullscreen(position=\'topright\').add_to(pdam_map)\n\n# Save interactive map to HTML file\nout_map_file = OUTPUT_MAPS / \'pdam_peta_interaktif_final.html\'\npdam_map.save(str(out_map_file))\nfile_size = os.path.getsize(out_map_file)\n\nprint(\'=\' * 60)\nprint(\'[OK] Interactive geospatial map updated and saved successfully!\')\nprint(f\'     File: {out_map_file}\')\nprint(f\'     File Size: {file_size/1024/1024:.2f} MB\')\nprint(f\'     Total Markers: {count:,}\')\nprint(\'=\' * 60)\n'),
    md('## 11.6 Display Interactive Web-GIS Map in Notebook'),
    code("# ===============================================================\n# Munculkan peta langsung di notebook\n# ===============================================================\nprint('[MAP] Interactive Geospatial Web-GIS Map - PDAM Purbalingga')\nprint('   - Click customer markers to inspect detailed popup card & sparkline')\nprint('   - Use top-right layer control to switch between satellite and street basemaps')\nprint('   - Compass rose (N/S/E/W) located in upper left')\nprint('   - Color-coded customer segmentation legend located in lower left')\nprint()\ndisplay(pdam_map)\n"),
    md('## 11.7 Statistical Summary of Mapped Customers\n\nStatistical breakdown of mapped customers across K-Means clusters and ANN spike anomaly categories.'),
    code("# ===============================================================\n# Mapping summary statistics table\n# ===============================================================\nprint('\\n' + '='*55)\nprint('[INTERACTIVE MAP STATISTICAL SUMMARY]')\nprint('='*55)\n\n# Cluster distribution\nprint('\\nK-Means Customer Segmentation Distribution:')\ncluster_summary = cust_geo['cluster_label'].value_counts().reset_index()\ncluster_summary.columns = ['Cluster', 'Customer Count']\ncluster_summary['Percentage'] = (cluster_summary['Customer Count'] / cluster_summary['Customer Count'].sum() * 100).round(1)\ncluster_summary['Percentage'] = cluster_summary['Percentage'].astype(str) + '%'\ndisplay(cluster_summary)\n\n# Spike distribution\nprint('\\nANN Regression & Spike Anomaly Distribution:')\nspike_summary = cust_geo['spike_status'].value_counts().reset_index()\nspike_summary.columns = ['Status', 'Customer Count']\nspike_summary['Percentage'] = (spike_summary['Customer Count'] / spike_summary['Customer Count'].sum() * 100).round(1)\nspike_summary['Percentage'] = spike_summary['Percentage'].astype(str) + '%'\ndisplay(spike_summary)\n\n# Cross-tabulation\nprint('\\nCross-Tabulation: Cluster vs Anomaly Status:')\nct = pd.crosstab(cust_geo['cluster_label'], cust_geo['spike_status'], margins=True)\ndisplay(ct)\n\nprint(f'\\nTotal mapped customers: {len(cust_geo):,}')\nprint(f'Map center coordinates: ({center_lat:.4f}, {center_lon:.4f})')\nprint(f'HTML Map File: {out_map_file}')\n"),
])

